# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.34.0/ankra-cli-darwin-arm64"
      sha256 "64f8d567e104d7750ec3b1e0032484413e856c31c4d1a900dce929ea4ddba0cf"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.34.0/ankra-cli-darwin-amd64"
      sha256 "456500c602f4390d1b3d541a7c4a534d9dc39aa18a2c362704ab15c636f25c8e"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.34.0/ankra-cli-linux-arm64"
      sha256 "c6d027f6687c460492729ffd09f1cbe480c97748c8eac08e40497060c05d4450"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.34.0/ankra-cli-linux-amd64"
